-- SILVER_AP_INVOICES PRD update: adds Baan (SRC-2025-003) and Workday (SRC-2025-004).
-- Generated by the prd-to-silver project skill. Validation queries at the bottom.
USE ROLE SNOWFLAKE_LEARNING_ROLE;
USE WAREHOUSE SNOWFLAKE_LEARNING_WH;

CREATE OR ALTER DYNAMIC TABLE SNOWFLAKE_LEARNING_DB.SAISRISATYA_COCO_PIPELINE_LAB.SILVER_AP_INVOICES
  TARGET_LAG = '1 hour'
  WAREHOUSE = SNOWFLAKE_LEARNING_WH
  REFRESH_MODE = INCREMENTAL
  INITIALIZE = ON_CREATE
  COMMENT = 'Silver AP invoices: SAP + Oracle + Baan + Workday normalized to a common schema (Lab 0 Demo 2, PRD BR-001..BR-010)'
AS
-- SAP (Phase 1)
SELECT INVOICE_ID, INVOICE_NUMBER, VENDOR_ID, VENDOR_NAME, INVOICE_DATE, DUE_DATE,
       INVOICE_AMOUNT, CURRENCY_CODE, PAYMENT_TERMS, PO_NUMBER, LINE_DESCRIPTION,
       GL_ACCOUNT, COST_CENTER, APPROVAL_STATUS, CREATED_AT, 'SAP' AS SOURCE_SYSTEM
FROM SNOWFLAKE_LEARNING_DB.SAISRISATYA_COCO_SOURCE_DATA.BRONZE_SAP_AP_INVOICES
UNION ALL
-- Oracle (Phase 1): VALIDATED -> APPROVED (BR-001)
SELECT INV_ID, INV_NUM, SUPPLIER_ID, SUPPLIER_NAME, INV_DATE, PAYMENT_DUE_DATE,
       TOTAL_AMOUNT, CURRENCY, TERMS_CODE, PURCHASE_ORDER, DESCRIPTION,
       ACCOUNT_CODE, DEPT_CODE,
       CASE UPPER(STATUS) WHEN 'VALIDATED' THEN 'APPROVED' ELSE UPPER(STATUS) END,
       CREATION_DATE, 'ORACLE'
FROM SNOWFLAKE_LEARNING_DB.SAISRISATYA_COCO_SOURCE_DATA.BRONZE_ORACLE_AP_INVOICES
UNION ALL
-- Baan (SRC-2025-003): POSTED -> APPROVED (BR-001); dedup on invoice number, latest created wins (BR-003)
SELECT BAN_INVOICE_ID, BAN_INVOICE_REF, BAN_VENDOR_CODE, BAN_VENDOR_DESC, BAN_INV_DATE, BAN_PAY_DATE,
       BAN_AMOUNT, BAN_CURR, BAN_PAY_TERMS, BAN_PO_REF, BAN_LINE_DESC,
       BAN_GL_CODE, BAN_COST_CTR,
       CASE UPPER(BAN_STATUS) WHEN 'POSTED' THEN 'APPROVED' ELSE UPPER(BAN_STATUS) END,
       BAN_CREATED, 'BAAN'
FROM SNOWFLAKE_LEARNING_DB.SAISRISATYA_COCO_SOURCE_DATA.BRONZE_BAAN_AP_INVOICES
QUALIFY ROW_NUMBER() OVER (PARTITION BY BAN_INVOICE_REF ORDER BY BAN_CREATED DESC, BAN_INVOICE_ID DESC) = 1
UNION ALL
-- Workday (SRC-2025-004): Approved -> APPROVED, In Review -> PENDING (BR-001)
SELECT WD_INVOICE_ID, WD_INVOICE_NUM, WD_SUPPLIER_ID, WD_SUPPLIER_NAME, WD_INVOICE_DATE, WD_DUE_DATE,
       WD_AMOUNT, WD_CURRENCY, WD_PAY_TERMS, WD_PO_NUMBER, WD_MEMO,
       WD_LEDGER_ACCOUNT, WD_COST_CENTER,
       CASE UPPER(WD_APPROVAL_STATUS) WHEN 'APPROVED' THEN 'APPROVED' WHEN 'IN REVIEW' THEN 'PENDING' ELSE UPPER(WD_APPROVAL_STATUS) END,
       WD_CREATED_DATE, 'WORKDAY'
FROM SNOWFLAKE_LEARNING_DB.SAISRISATYA_COCO_SOURCE_DATA.BRONZE_WORKDAY_AP_INVOICES;

-- ===================== Validation =====================
-- V1: row counts per source vs bronze (Baan net of BR-003 dedup). Expect COUNT_MATCH = TRUE for all 4.
WITH bronze AS (
    SELECT 'SAP' AS SOURCE_SYSTEM, COUNT(*) AS EXPECTED_ROWS FROM SNOWFLAKE_LEARNING_DB.SAISRISATYA_COCO_SOURCE_DATA.BRONZE_SAP_AP_INVOICES
    UNION ALL SELECT 'ORACLE', COUNT(*) FROM SNOWFLAKE_LEARNING_DB.SAISRISATYA_COCO_SOURCE_DATA.BRONZE_ORACLE_AP_INVOICES
    UNION ALL SELECT 'BAAN', COUNT(DISTINCT BAN_INVOICE_REF) FROM SNOWFLAKE_LEARNING_DB.SAISRISATYA_COCO_SOURCE_DATA.BRONZE_BAAN_AP_INVOICES
    UNION ALL SELECT 'WORKDAY', COUNT(*) FROM SNOWFLAKE_LEARNING_DB.SAISRISATYA_COCO_SOURCE_DATA.BRONZE_WORKDAY_AP_INVOICES
),
silver AS (
    SELECT SOURCE_SYSTEM, COUNT(*) AS SILVER_ROWS, SUM(INVOICE_AMOUNT) AS SILVER_AMOUNT
    FROM SNOWFLAKE_LEARNING_DB.SAISRISATYA_COCO_PIPELINE_LAB.SILVER_AP_INVOICES GROUP BY SOURCE_SYSTEM
)
SELECT b.SOURCE_SYSTEM, b.EXPECTED_ROWS, s.SILVER_ROWS, s.SILVER_AMOUNT, b.EXPECTED_ROWS = s.SILVER_ROWS AS COUNT_MATCH
FROM bronze b LEFT JOIN silver s ON s.SOURCE_SYSTEM = b.SOURCE_SYSTEM ORDER BY 1;

-- V2: only standard statuses (BR-001). Expect 0 rows.
SELECT SOURCE_SYSTEM, APPROVAL_STATUS, COUNT(*) AS N
FROM SNOWFLAKE_LEARNING_DB.SAISRISATYA_COCO_PIPELINE_LAB.SILVER_AP_INVOICES
WHERE APPROVAL_STATUS NOT IN ('APPROVED', 'PENDING') GROUP BY 1, 2;

-- V3: no duplicate business keys per source (BR-003). Expect 0 rows.
SELECT SOURCE_SYSTEM, INVOICE_NUMBER, COUNT(*) AS N
FROM SNOWFLAKE_LEARNING_DB.SAISRISATYA_COCO_PIPELINE_LAB.SILVER_AP_INVOICES
GROUP BY 1, 2 HAVING COUNT(*) > 1;

-- V4: required columns populated. Expect 0 rows.
SELECT SOURCE_SYSTEM, COUNT(*) AS ROWS_WITH_NULL_REQUIRED
FROM SNOWFLAKE_LEARNING_DB.SAISRISATYA_COCO_PIPELINE_LAB.SILVER_AP_INVOICES
WHERE INVOICE_ID IS NULL OR INVOICE_NUMBER IS NULL OR VENDOR_ID IS NULL OR VENDOR_NAME IS NULL
   OR INVOICE_DATE IS NULL OR DUE_DATE IS NULL OR INVOICE_AMOUNT IS NULL OR CURRENCY_CODE IS NULL
   OR GL_ACCOUNT IS NULL OR COST_CENTER IS NULL OR APPROVAL_STATUS IS NULL OR CREATED_AT IS NULL
GROUP BY 1;

-- V5: DT health after the change.
SHOW DYNAMIC TABLES LIKE 'SILVER_AP_INVOICES' IN SCHEMA SNOWFLAKE_LEARNING_DB.SAISRISATYA_COCO_PIPELINE_LAB;
